import{c as a,Q as s,j as e,m as i}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuChat 插件联动","description":"","frontmatter":{"title":"YuChat 插件联动"},"headers":[],"relativePath":"plugins/items/yu-chat/api.md","filePath":"plugins/items/yu-chat/api.md"}'),d={name:"plugins/items/yu-chat/api.md"};function h(l,t,n,p,r,o){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="yuchat-插件联动" tabindex="-1">YuChat 插件联动 <a class="header-anchor" href="#yuchat-插件联动" aria-label="Permalink to &quot;YuChat 插件联动&quot;">​</a></h1><p>YuChat 当前主要通过 Bukkit 命令、PlaceholderAPI 变量、LuckPerms API、Vault、PlayerPoints、配置文件和数据库存储完成联动。对大多数服务器而言，这些入口已经能覆盖菜单展示、计分板、TAB、经济扣费、聊天转发和权限组显示。</p><h2 id="placeholderapi" tabindex="-1">PlaceholderAPI <a class="header-anchor" href="#placeholderapi" aria-label="Permalink to &quot;PlaceholderAPI&quot;">​</a></h2><p>安装 PlaceholderAPI 后，YuChat 可注册 <code>%yuchat_*%</code> 变量供外部插件读取。常用接入：</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐变量</th></tr></thead><tbody><tr><td>TAB 列表</td><td><code>%yuchat_tab%</code>、<code>%yuchat_nickname%</code>、<code>%yuchat_title%</code></td></tr><tr><td>头顶名</td><td><code>%yuchat_prefix%</code>、<code>%yuchat_title%</code>、<code>%yuchat_nickname%</code>、<code>%yuchat_suffix%</code></td></tr><tr><td>菜单展示</td><td><code>%yuchat_title%</code>、<code>%yuchat_nickname%</code>、<code>%yuchat_signature%</code></td></tr><tr><td>排查显示</td><td><code>%yuchat_prefix_raw%</code>、<code>%yuchat_suffix_raw%</code>、<code>%yuchat_selected_title%</code></td></tr></tbody></table><p>更多变量见 <a href="/YuPluginHub/plugins/items/yu-chat/placeholders">PlaceholderAPI</a>。</p><h2 id="luckperms" tabindex="-1">LuckPerms <a class="header-anchor" href="#luckperms" aria-label="Permalink to &quot;LuckPerms&quot;">​</a></h2><p>YuChat 会优先通过 LuckPerms API 读取玩家 prefix、suffix 和 meta。<code>prefix-suffix.prefix.parts</code> 与 <code>prefix-suffix.suffix.parts</code> 可组合多个片段：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prefix-suffix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    parts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prefix&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;meta:clan_prefix&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  suffix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    parts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;suffix&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;meta:rank_suffix&quot;</span></span></code></pre></div><p>如果 LuckPerms API 不可用，也可以在 <code>placeholder-fallback</code> 中配置 PAPI 兜底变量。</p><h2 id="vault-与-playerpoints" tabindex="-1">Vault 与 PlayerPoints <a class="header-anchor" href="#vault-与-playerpoints" aria-label="Permalink to &quot;Vault 与 PlayerPoints&quot;">​</a></h2><p>YuChat 可把昵称、昵称效果、消息效果、个性签名、死亡消息和称呼接入经济系统。</p><table tabindex="0"><thead><tr><th>依赖</th><th>用途</th></tr></thead><tbody><tr><td>Vault</td><td>金币扣费，需要再安装实际经济插件。</td></tr><tr><td>PlayerPoints</td><td>点券扣费。</td></tr><tr><td>Vault + PlayerPoints</td><td>支持 <code>both</code> 双扣或 <code>either</code> 二选一。</td></tr></tbody></table><p>称呼价格可在 <code>titles.yml</code> 的 <code>payment</code> 节点中设置，通用功能价格可在 <code>config.yml -&gt; economy</code> 中设置。</p><h2 id="tab-与头顶名插件" tabindex="-1">TAB 与头顶名插件 <a class="header-anchor" href="#tab-与头顶名插件" aria-label="Permalink to &quot;TAB 与头顶名插件&quot;">​</a></h2><p>若外部 TAB 插件接管玩家列表或头顶名，Bukkit 原生同步可能被覆盖。推荐在外部插件中使用 YuChat PAPI 变量，而不是依赖 Bukkit displayName。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">customtabname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%yuchat_tab%&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">customtagname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%yuchat_prefix%%yuchat_title% %yuchat_nickname%%yuchat_suffix%&quot;</span></span></code></pre></div><h2 id="easybot-与群组互联" tabindex="-1">EasyBot 与群组互联 <a class="header-anchor" href="#easybot-与群组互联" aria-label="Permalink to &quot;EasyBot 与群组互联&quot;">​</a></h2><p>默认配置会保留 Bukkit 原始聊天事件，适合 EasyBot、聊天记录、群组互联类插件继续监听 <code>AsyncPlayerChatEvent</code>。</p><p>需要聊天内悬浮时再开启：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">chat-format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  component-broadcast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>开启组件广播后，YuChat 可能取消原聊天事件并自行广播 TextComponent。若群组互联收不到消息，优先关闭 <code>component-broadcast.enabled</code> 或关闭所有 <code>hover</code> 细分项。</p><h2 id="数据库联动" tabindex="-1">数据库联动 <a class="header-anchor" href="#数据库联动" aria-label="Permalink to &quot;数据库联动&quot;">​</a></h2><p>YuChat 支持 SQLite 与 MySQL。跨服共享时建议使用 MySQL，并保持所有子服：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>插件版本</td><td>保持一致。</td></tr><tr><td>配置版本</td><td>保持一致。</td></tr><tr><td><code>storage.table-prefix</code></td><td>保持一致。</td></tr><tr><td>称呼与效果文件</td><td>保持一致，避免已保存 ID 在某个子服不存在。</td></tr></tbody></table><p>外部程序读取数据库时只建议只读展示，不建议直接写入玩家数据表，避免与插件缓存、过期清理和保存流程冲突。</p><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>plugins/YuChat/config.yml</code></td><td>主配置。</td></tr><tr><td><code>plugins/YuChat/messages.yml</code></td><td>消息文本。</td></tr><tr><td><code>plugins/YuChat/gui.yml</code></td><td>GUI 布局。</td></tr><tr><td><code>plugins/YuChat/titles.yml</code></td><td>内置称呼。</td></tr><tr><td><code>plugins/YuChat/custom_titles.yml</code></td><td>管理员 GUI 创建的称呼。</td></tr><tr><td><code>plugins/YuChat/effects.yml</code></td><td>颜色与动态效果。</td></tr><tr><td><code>plugins/YuChat/yuchat.db</code></td><td>默认 SQLite 数据库。</td></tr><tr><td><code>plugins/YuChat/libs/</code></td><td>运行时依赖。</td></tr><tr><td><code>plugins/YuChat/runtime/</code></td><td>隔离 core jar。</td></tr></tbody></table><h2 id="bstats" tabindex="-1">bStats <a class="header-anchor" href="#bstats" aria-label="Permalink to &quot;bStats&quot;">​</a></h2><p>YuChat 内置 bStats Bukkit 统计：</p><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>插件 ID</td><td><code>31412</code></td></tr><tr><td>插件名</td><td><code>YuChat</code></td></tr><tr><td>软件类型</td><td><code>bukkit</code></td></tr></tbody></table>`,31)])])}const u=a(d,[["render",h]]);export{k as __pageData,u as default};
